/** 同步最新展开意图；关闭时保留出场内容，运行时刷新立即跟随逻辑状态。 */
function ownershipDisclosureChanged(event: Event) {
  if (event.target !== event.currentTarget) return
  const { open } = (event as CustomEvent<{ open: boolean }>).detail
  expanded.value = open
  if (open) {
    const details = event.currentTarget as HTMLDetailsElement
    bodyVisible.value = true
    void nextTick(() => refreshDisclosure(details))
  }
}
/** 原生最终关闭后卸载惰性内容；共享控制器出场期间的 open 不覆盖逻辑关闭意图。 */
function ownershipDisclosureToggled(event: Event) {
  if (event.target !== event.currentTarget) return
  const details = event.currentTarget as HTMLDetailsElement
  expanded.value = details.dataset.uiDisclosureOpen === undefined ? details.open : details.dataset.uiDisclosureOpen === 'true'
  bodyVisible.value = details.open
}
